/// <summary>
/// Bug 231840: CB501 - Disable Remove button for PO lines for ISP users
/// </summary>
internal final class METISPPurchLineStripDelete
{
    List poLinesToDelete;

}

Method.Source:
/// <summary>
/// Construct method
/// </summary>
/// <param name = "_poLinesToDelete"><c>List</c> of po lines to delete</param>
/// <returns></returns>
public static METISPPurchLineStripDelete construct(List _poLinesToDelete)
{
    return new METISPPurchLineStripDelete(_poLinesToDelete);
}

/// <summary>
/// New method
/// </summary>
/// <param name = "_poLinesToDelete"><c>List</c> of po lines to delete</param>
protected void new(List _poLinesToDelete)
{
    poLinesToDelete = _poLinesToDelete;
}

/// <summary>
/// Main method
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args _args)
{
    if (_args)
    {
        PurchLine purchLine = _args.record();
        FormDataSource fds = FormDataUtil::getFormDataSource(purchLine);

        if (purchLine)
        {
            boolean canDelete = true;

            // copied from Form\PurchTable\PurchLine_ds\validateDelete
            // validateDelete() will be triggered in METISPPurchLineStripDelete\deletePOLines
            str warning = purchLine.type(purchLine.purchTable()).getDeleteWarning();

            if (warning != "")
            {
                canDelete = (Box::yesNo(warning, DialogButton::No) == DialogButton::Yes);
            }
            else
            {
                // to simulate the FormDataSource\validateDelete call to Box::callSysBoxFormWait()
                canDelete = (Box::yesNo("@GLS93975", DialogButton::No, "@SYS28002") == DialogButton::Yes);
            }

            if (canDelete)
            {                   
                PurchLine purchLineDelete;
                List list = new List(Types::Record);

                for (purchLineDelete = fds.getFirst(1) ? fds.getFirst(1) : fds.cursor(); purchLineDelete; purchLineDelete = fds.getNext())
                {
                    list.addEnd(purchLineDelete);
                }

                METISPPurchLineStripDelete metISPPurchLineStripDelete = METISPPurchLineStripDelete::construct(list);
                metISPPurchLineStripDelete.run();                    
            }
        }
        else
        {
            ttsbegin;
            purchLine.delete();
            ttscommit;
        }

        fds.research(true);
    }
    else
    {
        throw error(Error::wrongUseOfFunction(funcName()));
    }
}

/// <summary>
/// Run method
/// </summary>
protected void run()
{
    if (this.validate())
    {
        this.deletePOLines();
    }
}

/// <summary>
/// Validate the list is not empty
/// </summary>
/// <returns>True if validation successful; otherwise, false.</returns>
protected boolean validate()
{
    boolean ret = true;

    if (poLinesToDelete.empty())
    {
        ret = checkFailed("@MET:NoPOLineSelectedDelete");
    }        

    return ret;
}

/// <summary>
/// Delete selected PO lines
/// </summary>
protected void deletePOLines()
{
    ListEnumerator le = poLinesToDelete.getEnumerator();
    PurchLine purchLine;
    PurchLineAllVersions purchLineAllVersions;

    while (le.moveNext())
    {
        try
        {
            ttsbegin;
            purchLine = le.current();

            // if the PO line is confirmed, ISP user cannot delete it
            select firstonly RecId from purchLineAllVersions where purchLineAllVersions.InventTransId == purchLine.InventTransId;

            if (!purchLineAllVersions)
            {
                if (purchLine.validateDelete())
                {
                    purchLine.delete();
                }
                else
                {
                    warning(strFmt("@MET:CannotDeletePOLine", purchLine.LineNumber, purchLine.ItemId));
                }
            }
            else
            {
                warning(strFmt("@MET:CannotDeletePOLineConfirmed", purchLine.LineNumber, purchLine.ItemId));
            }

            ttscommit;
        }
        catch (Exception::Error)
        {
            warning(strFmt("@MET:CannotDeletePOLine", purchLine.LineNumber, purchLine.ItemId));
        }
    }
}
